import{_ as e,o as t,c as n,e as r}from"./app-6c9584fa.js";const i={};function l(a,o){return t(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="给-ai-聊天里边发了一个-今天天气怎么样了-接下来-前端、后端、数据库、缓存、大模型等会怎么做吗-请给出一个细化的流程。越详细越好。" tabindex="-1"><a class="header-anchor" href="#给-ai-聊天里边发了一个-今天天气怎么样了-接下来-前端、后端、数据库、缓存、大模型等会怎么做吗-请给出一个细化的流程。越详细越好。" aria-hidden="true">#</a> 给 AI 聊天里边发了一个 “今天天气怎么样了”？接下来，前端、后端、数据库、缓存、大模型等会怎么做吗？ 请给出一个细化的流程。越详细越好。</h1><p>当用户在 AI 聊天框中输入“今天天气怎么样了？”并点击发送后，背后会触发一条复杂且精密的链路。为了实现“低延迟、高可靠、流式输出”的体验，现代 AI 应用（如 ChatGPT、Claude）通常会采用如下细化的处理流程：</p><hr><h2 id="_1-前端-frontend-阶段-用户交互与请求发起" tabindex="-1"><a class="header-anchor" href="#_1-前端-frontend-阶段-用户交互与请求发起" aria-hidden="true">#</a> 1. 前端（Frontend）阶段：用户交互与请求发起</h2><p><strong>① 拦截输入与状态更新（Optimistic UI）</strong></p><ul><li><strong>事件绑定</strong>：用户按下 <code>Enter</code> 或点击发送按钮，前端拦截默认提交事件。</li><li><strong>状态变更</strong>：前端立即将输入框清空，并将用户的消息内容渲染到聊天界面上（Optimistic UI，乐观更新），给用户一种“瞬间响应”的错觉。</li><li><strong>UI 状态</strong>：AI 的回复气泡出现，显示为“思考中...”或闪烁的光标（Typing Indicator），同时禁用发送按钮或将其变为“停止生成”按钮。</li></ul><p><strong>② 构建请求负载（Payload）</strong></p><ul><li>前端不会只发这一句话，而是会带上<strong>上下文（Context）</strong>。</li><li>从本地状态（如 Redux、Zustand 或 Vuex）中提取当前会话（Session）的 <code>session_id</code>、当前用户的 <code>user_id</code>，以及最近的几条历史对话（如果有配置前端截断）。</li><li>构建完成后，通常通过 <strong>SSE（Server-Sent Events）</strong> 或 <strong>WebSocket</strong> 发起请求，以便后续接收流式（Streaming）响应。</li></ul><hr><h2 id="_2-网关层-gateway-load-balancer-流量接入与安全校验" tabindex="-1"><a class="header-anchor" href="#_2-网关层-gateway-load-balancer-流量接入与安全校验" aria-hidden="true">#</a> 2. 网关层（Gateway / Load Balancer）：流量接入与安全校验</h2><p><strong>① 负载均衡与路由</strong></p><ul><li>请求首先到达 Nginx、APISIX 或云厂商的 API 网关。网关根据请求的路径（如 <code>/api/v1/chat/completions</code>）将其路由到对应的后端微服务（如 Chat Service）。</li></ul><p><strong>② 安全与鉴权（Authentication &amp; Authorization）</strong></p><ul><li><strong>Token 校验</strong>：网关或 Auth 服务解析请求头中的 JWT Token，验证用户身份是否合法、Token 是否过期。</li><li><strong>限流（Rate Limiting）</strong>：通过 Redis 检查该用户是否触发了频率限制（如“每分钟最多发 10 条消息”或“普通用户每天限额 50 条”）。如果超限，直接返回 <code>429 Too Many Requests</code>。</li></ul><hr><h2 id="_3-后端服务-backend-api-server-业务逻辑与上下文组装" tabindex="-1"><a class="header-anchor" href="#_3-后端服务-backend-api-server-业务逻辑与上下文组装" aria-hidden="true">#</a> 3. 后端服务（Backend / API Server）：业务逻辑与上下文组装</h2><p><strong>① 参数校验与风险控制（Safety Check）</strong></p><ul><li>验证请求参数的合法性（如消息是否为空、长度是否超过限制）。</li><li><strong>风控拦截</strong>：将文本发送给内部的风控微服务或敏感词过滤系统（通过本地词库或轻量级分类模型），检查是否包含违规内容。</li></ul><p><strong>② 从缓存与数据库获取上下文（Context Assembly）</strong></p><ul><li><strong>读取 Cache（Redis）</strong>： <ul><li>后端根据 <code>session_id</code> 去 Redis 中拉取该会话的<strong>近期历史记录</strong>（例如最近 10 轮对话），因为 LLM 本身是无状态的，必须每次把历史记录带上。</li></ul></li><li><strong>读取 Database（MySQL / PostgreSQL）</strong>： <ul><li>如果 Redis 中没有命中（Cache Miss），则去关系型数据库中查询历史记录，并将其回写到 Redis 中。</li><li>获取用户的个性化配置（如系统提示词 System Prompt：“你是一个傲娇的天气助手”）。</li></ul></li></ul><p><strong>③ 意图识别与 RAG/Tool 路由</strong></p><ul><li>现代复杂的 Agent 系统会在请求大模型之前，做一次<strong>意图路由（Semantic Router）</strong>。</li><li>识别到“天气”属于<strong>实时信息查询</strong>，因此系统知道不能单纯依赖大模型的内部知识（LLM 不知道今天的实时天气），而是需要触发 <strong>工具调用（Tool Calling / Function Calling）</strong>。</li></ul><hr><h2 id="_4-大模型-llm-与-agent-协同-思考与工具调用" tabindex="-1"><a class="header-anchor" href="#_4-大模型-llm-与-agent-协同-思考与工具调用" aria-hidden="true">#</a> 4. 大模型（LLM）与 Agent 协同：思考与工具调用</h2><p><strong>① 第一次 LLM 请求（意图与工具决策）</strong></p><ul><li>后端将组装好的 Prompt（包含系统提示词、历史记录、当前问题“今天天气怎么样了”，以及<strong>可用工具列表</strong>：如 <code>get_weather(location, date)</code>）发送给大模型（如 GPT-4、Claude-3）。</li><li><strong>LLM 推理</strong>：LLM 分析发现问题需要实时天气，但发现缺少“地点”信息（假设用户没在上下文中提过）。</li><li><strong>追问（可选）</strong>：如果 LLM 觉得信息不足，它可能会直接返回文本：“请问您在哪个城市？”。</li><li><strong>假设已知位置</strong>：假设通过用户的 IP 逆向解析，或者用户之前的聊天提到了“我在北京”，LLM 决定调用工具。它返回一个特殊的 JSON 结构，告诉后端：“我要调用 <code>get_weather</code> 函数，参数是 <code>{&quot;location&quot;: &quot;北京&quot;, &quot;date&quot;: &quot;today&quot;}</code>”。</li></ul><p><strong>② 后端执行工具调用（External API）</strong></p><ul><li>后端解析到 LLM 的工具调用请求，暂停流式输出。</li><li>后端去请求第三方的天气 API（如和风天气、OpenWeather）。</li><li>天气 API 返回数据：<code>{&quot;temp&quot;: &quot;25℃&quot;, &quot;condition&quot;: &quot;晴转多云&quot;, &quot;wind&quot;: &quot;微风&quot;}</code>。</li></ul><p><strong>③ 第二次 LLM 请求（生成最终回复）</strong></p><ul><li>后端将天气 API 返回的结果（作为 Tool Message）追加到对话历史中，<strong>再次</strong>发送给大模型。</li><li>LLM 根据真实天气数据，开始生成自然语言回复：“北京今天天气不错哦，晴转多云，气温大约 25℃，微风拂面，很适合出门散步呢！”。</li></ul><hr><h2 id="_5-响应返回-streaming-后端到前端的流式传输" tabindex="-1"><a class="header-anchor" href="#_5-响应返回-streaming-后端到前端的流式传输" aria-hidden="true">#</a> 5. 响应返回（Streaming）：后端到前端的流式传输</h2><p><strong>① 后端流式接收与转发</strong></p><ul><li>后端通过 HTTP/2 从大模型厂商（如 OpenAI）接收流式响应（Chunk by Chunk）。</li><li>每收到一个 Token（一个字或几个字母），后端立刻通过 SSE 连接，将其包装成特定的格式（如 <code>data: {&quot;content&quot;: &quot;北&quot;}\\n\\n</code>）推送给前端。</li></ul><p><strong>② 异步持久化（Database &amp; Cache）</strong></p><ul><li><strong>不阻塞主流程</strong>：在流式输出结束（收到 <code>[DONE]</code> 标记）后，后端会在后台开启异步任务。</li><li><strong>更新 Redis</strong>：将新的一轮问答（用户的提问 + AI 的完整回答）推入 Redis 的 Session 历史列表中。</li><li><strong>持久化到 DB</strong>：将这轮对话写入 MySQL/PostgreSQL 以作永久保存。</li><li><strong>Token 计费</strong>：计算本次请求消耗的 Prompt Tokens 和 Completion Tokens，写入计费系统，扣除用户额度。</li><li><strong>向量化（可选）</strong>：如果系统开启了长期记忆（Long-term Memory），会将这轮对话发送给 Embedding 模型转为向量，存入向量数据库（如 Milvus / Qdrant），供未来 RAG 检索。</li></ul><hr><h2 id="_6-前端-frontend-阶段-流式渲染与体验优化" tabindex="-1"><a class="header-anchor" href="#_6-前端-frontend-阶段-流式渲染与体验优化" aria-hidden="true">#</a> 6. 前端（Frontend）阶段：流式渲染与体验优化</h2><p><strong>① 接收数据块并拼接</strong></p><ul><li>前端通过 <code>EventSource</code> 或 <code>fetch</code> 的 <code>ReadableStream</code> 监听到数据块。</li><li>将收到的增量文本不断拼接到当前 AI 回复的状态变量中。</li></ul><p><strong>② Markdown 实时渲染与代码高亮</strong></p><ul><li>前端将不断增长的字符串传入 Markdown 解析器（如 <code>marked</code> 或 <code>react-markdown</code>）。</li><li>为了防止渲染闪烁，通常会有防抖（Debounce）处理或特定的流式 Markdown 渲染优化。</li></ul><p><strong>③ 自动滚动与交互恢复</strong></p><ul><li>随着文字不断增多，气泡变大，前端需要监听 DOM 变化，自动将聊天窗口滚动到底部（Scroll to bottom），保持最新文字在视野内。</li><li>当收到后端的“结束”信号时，前端将“停止生成”按钮恢复为“发送”按钮，允许用户进行下一次对话。</li></ul><hr><h3 id="总结链路图" tabindex="-1"><a class="header-anchor" href="#总结链路图" aria-hidden="true">#</a> 总结链路图</h3><p><code>用户点击发送</code> -&gt; <code>前端乐观更新UI并建立SSE</code> -&gt; <code>网关鉴权限流</code> -&gt; <code>后端拉取Redis历史会话</code> -&gt; <code>后端组装Prompt并调用LLM</code> -&gt; <code>LLM决策需要调用天气API</code> -&gt; <code>后端请求外部天气服务</code> -&gt; <code>后端将天气数据给回LLM</code> -&gt; <code>LLM生成自然语言回复(流式)</code> -&gt; <code>后端通过SSE将Token转发给前端</code> -&gt; <code>前端实时打字机渲染</code> -&gt; <code>(后台)后端异步写入DB和更新Redis、扣减Token余额</code>。</p>',47)])])}const d=e(i,[["render",l],["__file","今天天气怎么样了.html.vue"]]);export{d as default};
